 package endpoint

-import "net/url"
+import (
+	"fmt"
+	"net"
+	"net/url"
+	"strings"
+)

 func Validate(raw string, allowedHosts []string) (*url.URL, error) {
-	return url.Parse(raw)
+	u, err := url.Parse(raw)
+	if err != nil {
+		return nil, fmt.Errorf("parsing url: %w", err)
+	}
+
+	if !u.IsAbs() || !strings.EqualFold(u.Scheme, "https") {
+		return nil, fmt.Errorf("url must be an absolute https url, got scheme %q", u.Scheme)
+	}
+
+	if u.User != nil {
+		return nil, fmt.Errorf("url must not contain userinfo")
+	}
+
+	hostname := u.Hostname()
+	if hostname == "" {
+		return nil, fmt.Errorf("url must contain a hostname")
+	}
+
+	if net.ParseIP(hostname) != nil {
+		return nil, fmt.Errorf("url hostname must not be an IP literal: %q", hostname)
+	}
+
+	if len(allowedHosts) == 0 {
+		return nil, fmt.Errorf("no allowed hosts configured")
+	}
+
+	lowerHost := strings.ToLower(hostname)
+	allowed := false
+	for _, h := range allowedHosts {
+		if strings.ToLower(h) == lowerHost {
+			allowed = true
+			break
+		}
+	}
+	if !allowed {
+		return nil, fmt.Errorf("host %q is not in the allowed hosts list", hostname)
+	}
+
+	return u, nil
 }
